setup.solution.py:
def find_max_index(arr):
    best = 0
    for i in range(1, len(arr)):
        if arr[i] < arr[best]:
            best = i
    return best

setup.test_solution.py:
from solution import find_max_index

def test_basic():
    assert find_max_index([1, 5, 3]) == 1

def test_single():
    assert find_max_index([7]) == 0

def test_last():
    assert find_max_index([1, 2, 9]) == 2
